<template>
<div>
  <div class="row d-grid vh-100">
    <div class="col-md-8 col-lg-5 mx-auto align-self-center">
     <div class="card w-100 border border-dashed">
       <div class="card-body py-5">
         <h3 class="w-100 text-center">{{result.title}}</h3>
         <b class="w-100 text-center d-block">{{result.message}}</b>
         <h3 v-if="title" class="w-100 text-center">{{title}}</h3>
         <b v-if="message" class="w-100 text-center d-block">{{message}}</b>
         <div v-if="result.code" class="d-flex justify-content-between"><b>شماره سفارش</b><b>{{result.code}}</b></div>
         <div v-if="result.amount" class="d-flex justify-content-between"><b>پرداخت شما</b><b>{{result.amount}}</b></div>
         <div v-if="result.referenceId" class="d-flex justify-content-between"><b>کد پیگیری تراکنش</b><b>{{result.referenceId}}</b></div>
       </div>
     </div>
    </div>

  </div>
</div>
</template>

<script>
import {useRoute} from "vue-router/dist/vue-router";
import App from "@/App.vue";
import {onMounted, ref} from "vue";

export default {
  setup(){
    const route = useRoute()
    const url = App.setup().url;
    const authority = route.query.Authority
    const status = route.query.Status
    const order_id = route.query.oid
    const result = ref({})
    const title = ref('')
    const message = ref('')

    const verifyPayment = ()=>{
      axios.post(url + '/api/verify/payment',
          {},
          {
            params: {
              Authority: authority,
              Status: status,
              order_id: order_id
            }

      }).then((response)=>{
        if(response.status === 200){
          result.value = response.data
        }else{
          result.value = response.data
        }
      }).then(()=>{
        if(route.query.Status === 'NOK'){
          title.value = 'تراکنش انجام نشد'
          message.value = 'لطفا پس از بررسی صورت حساب بانکی خود، مجدد اقدام کنید.'
        }
      }).then(()=>{
      updateUser();
      }).catch((error)=>{
        console.error(error)
        if(route.query.Status === 'NOK'){
          title.value = 'تراکنش انجام نشد'
          message.value = 'لطفا پس از بررسی صورت حساب بانکی خود، مجدد اقدام کنید.'
        }
        updateUser();
      })
      ;
    };

    onMounted(()=>{
      console.log(route)
      verifyPayment();
    })
    const updateUser=()=>{
      let user = {}
      let cart = {}
      axios.get(url+'/api/user/'+JSON.parse(localStorage.getItem('user')).id)
          .then((response)=>{
            user = response.data;
            localStorage.setItem('user', JSON.stringify(user.value));
          })
          .then(()=>{
            document.getElementById('sum').innerText = cart.sum;
            document.getElementById('sum2').innerText = cart.sum;
            if(cart.sum === 0){
              document.getElementById('sum').style.display='none';
              document.getElementById('sum2').style.display='none';
            }
          })
          .catch((error) => console.error(error))
    }
    return{
      route, verifyPayment, authority,status,order_id,result,updateUser,title,message
    }
  }
}
</script>

